    <script>
        document.addEventListener('DOMContentLoaded', () => {
            const gallery = document.querySelector('.product-gallery');

            if (!gallery) {
                return;
            }

            const mainImage = gallery.querySelector('.product-gallery-image');
            const thumbs = gallery.querySelectorAll('.product-gallery-thumb');
            const prevButton = gallery.querySelector('.product-gallery-prev');
            const nextButton = gallery.querySelector('.product-gallery-next');
            const zoomButton = gallery.querySelector('.product-gallery-zoom');

            if (!mainImage) {
                return;
            }

            const images = [];

            // Если есть миниатюры — берем изображения из них
            if (thumbs.length) {
                thumbs.forEach(thumb => {
                    const image = thumb.querySelector('img');

                    if (image) {
                        images.push({
                            src: image.src,
                            type: 'image',
                            caption: image.alt
                        });
                    }
                });
            } else {
                // Если фотография только одна — берем её из главного изображения
                images.push({
                    src: mainImage.src,
                    type: 'image',
                    caption: mainImage.alt
                });
            }

            if (!images.length) {
                return;
            }

            let currentIndex = 0;

            function showSlide(index) {
                if (index < 0) {
                    index = images.length - 1;
                }

                if (index >= images.length) {
                    index = 0;
                }

                currentIndex = index;

                mainImage.src = images[currentIndex].src;

                thumbs.forEach((thumb, thumbIndex) => {
                    thumb.classList.toggle(
                        'active',
                        thumbIndex === currentIndex
                    );
                });
            }

            function openGallery(index = currentIndex) {
                if (typeof Fancybox === 'undefined') {
                    console.error('Fancybox не загружен');
                    return;
                }

                Fancybox.show(images, {
                    startIndex: index,

                    animated: true,

                    showClass: 'f-fadeIn',

                    hideClass: 'f-fadeOut',

                    Toolbar: {
                        display: {
                            left: [],
                            middle: ['infobar'],
                            right: ['zoom', 'close']
                        }
                    },

                    Thumbs: {
                        type: 'classic'
                    },

                    Carousel: {
                        infinite: images.length > 1
                    }
                });
            }

            // Кнопки перелистывания
            prevButton?.addEventListener('click', () => {
                showSlide(currentIndex - 1);
            });

            nextButton?.addEventListener('click', () => {
                showSlide(currentIndex + 1);
            });

            // Миниатюры
            thumbs.forEach((thumb, index) => {
                thumb.addEventListener('click', () => {
                    showSlide(index);
                });

                thumb.addEventListener('dblclick', () => {
                    openGallery(index);
                });
            });

            // Клик по главной фотографии
            mainImage.addEventListener('click', () => {
                openGallery(currentIndex);
            });

            // Кнопка увеличения
            zoomButton?.addEventListener('click', () => {
                openGallery(currentIndex);
            });

            showSlide(0);
        });
    </script>

    <script>
        document.addEventListener('click', function (event) {

            const question = event.target.closest('.faq-question');

            if (!question) {
                return;
            }

            const faqItem = question.closest('.faq-item');

            if (!faqItem) {
                return;
            }

            const answer = faqItem.querySelector('.faq-answer');
            const icon = faqItem.querySelector('.faq-icon');

            if (!answer || !icon) {
                return;
            }

            const isOpen = faqItem.classList.contains('active');

            // Закрываем все остальные вопросы
            document.querySelectorAll('.faq-item').forEach(item => {
                item.classList.remove('active');

                const itemIcon = item.querySelector('.faq-icon');

                if (itemIcon) {
                    itemIcon.textContent = '+';
                }
            });

            // Если текущий был закрыт — открываем его
            if (!isOpen) {
                faqItem.classList.add('active');
                icon.textContent = '−';
            }

        });
    </script>


    <script>
        document.addEventListener('DOMContentLoaded', function () {

            const buttons = document.querySelectorAll('.product-tabs-button');
            const contents = document.querySelectorAll('.product-tabs-content');

            buttons.forEach(button => {

                button.addEventListener('click', function () {

                    const tab = this.dataset.tab;

                    // Убираем active со всех кнопок
                    buttons.forEach(btn => {
                        btn.classList.remove('active');
                    });

                    // Убираем active со всех блоков
                    contents.forEach(content => {
                        content.classList.remove('active');
                    });

                    // Активируем нажатую кнопку
                    this.classList.add('active');

                    // Показываем соответствующий блок
                    const content = document.querySelector(
                        `.product-tabs-content[data-content="${tab}"]`
                    );

                    if (content) {
                        content.classList.add('active');
                    }

                });

            });

        });
    </script>


    <script src="https://cdn.jsdelivr.net/npm/@fancyapps/ui@6.1/dist/fancybox/fancybox.umd.js"></script>

